+        return WeightedGraph.builder(5)
+                .addEdge(0, 1, 4)
+                .addEdge(0, 3, 5)
+                .addEdge(1, 2, 1)
+                .addEdge(1, 4, 6)
+                .addEdge(2, 0, 2)
+                .addEdge(2, 3, 3)
+                .addEdge(3, 2, 1)
+                .addEdge(3, 4, 2)
+                .addEdge(4, 0, 1)
+                .addEdge(4, 3, 4)
+                .build();
+    }
+}
